class Solution {
public:
    int numSquarefulPerms(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<bool> visited(n, false);

        auto isSquare = [](int x) {
            int r = round(sqrt(x));
            return r * r == x;
        };

        auto dfs = [&](auto& self, int last, int count) -> int {
            if (count == n) return 1;
            int total = 0;
            for (int i = 0; i < n; ++i) {
                if (visited[i]) continue;
                if (i > 0 && nums[i] == nums[i - 1] && !visited[i - 1]) continue;
                if (last != -1 && !isSquare(last + nums[i])) continue;
                visited[i] = true;
                total += self(self, nums[i], count + 1);
                visited[i] = false;
            }
            return total;
        };

        return dfs(dfs, -1, 0);
    }
};

class Solution {
    public int numSquarefulPerms(int[] nums) {
        Arrays.sort(nums);
        boolean[] visited = new boolean[nums.length];
        return dfs(nums, visited, -1, 0);
    }

    private boolean isSquare(int x) {
        int r = (int) Math.round(Math.sqrt(x));
        return r * r == x;
    }

    private int dfs(int[] nums, boolean[] visited, int last, int count) {
        if (count == nums.length) return 1;
        int total = 0;
        for (int i = 0; i < nums.length; ++i) {
            if (visited[i]) continue;
            if (i > 0 && nums[i] == nums[i - 1] && !visited[i - 1]) continue;
            if (last != -1 && !isSquare(last + nums[i])) continue;
            visited[i] = true;
            total += dfs(nums, visited, nums[i], count + 1);
            visited[i] = false;
        }
        return total;
    }
}

var numSquarefulPerms = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const visited = new Array(n).fill(false);

    const isSquare = (x) => {
        const r = Math.round(Math.sqrt(x));
        return r * r === x;
    };

    const dfs = (last, count) => {
        if (count === n) return 1;
        let total = 0;
        for (let i = 0; i < n; i++) {
            if (visited[i]) continue;
            if (i > 0 && nums[i] === nums[i - 1] && !visited[i - 1]) continue;
            if (last !== null && !isSquare(last + nums[i])) continue;
            visited[i] = true;
            total += dfs(nums[i], count + 1);
            visited[i] = false;
        }
        return total;
    };

    return dfs(null, 0);
};
